# Cull Context Assembler: Schemas

**Service Name:** cull
**Status:** Draft
**Last Updated:** December 2025

---

## 1. Overview

Cull uses:
- **JSON** for API requests/responses and runtime data
- **YAML** for configuration files

This document defines all schemas for both formats.

---

## 2. API Schemas (JSON)

### 2.1 Assembly Request

```json
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "AssemblyRequest",
  "type": "object",
  "oneOf": [
    {
      "required": ["scope", "token_budget"]
    },
    {
      "required": ["artifact_ids", "token_budget"]
    }
  ],
  "properties": {
    "scope": {
      "$ref": "#/definitions/Scope"
    },
    "artifact_ids": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Specific artifact IDs to fetch (alternative to scope)"
    },
    "token_budget": {
      "type": "integer",
      "minimum": 1,
      "description": "Maximum tokens in assembled context"
    },
    "priority_rules": {
      "type": "string",
      "default": "default",
      "description": "Name of priority rule set to apply"
    },
    "include_audit": {
      "type": "boolean",
      "default": false,
      "description": "Include detailed audit trail in response"
    },
    "encoding": {
      "type": "string",
      "default": "cl100k_base",
      "description": "Tokenizer encoding for counting"
    }
  },
  "definitions": {
    "Scope": {
      "type": "object",
      "properties": {
        "domains": {
          "type": "array",
          "items": { "type": "string" },
          "description": "Domains to include (empty = all)"
        },
        "categories": {
          "type": "array",
          "items": { "type": "string" },
          "description": "Categories to include (empty = all)"
        },
        "tags": {
          "type": "array",
          "items": { "type": "string" },
          "description": "Required tags (AND logic)"
        },
        "providers": {
          "type": "array",
          "items": { "type": "string" },
          "description": "Providers to query (empty = all enabled)"
        }
      }
    }
  }
}
```

### 2.2 Assembly Response

```json
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "AssemblyResponse",
  "type": "object",
  "required": ["assembled_context", "token_count", "artifacts_included", "overflow"],
  "properties": {
    "assembled_context": {
      "type": "string",
      "description": "Concatenated content ready for LLM"
    },
    "token_count": {
      "type": "integer",
      "description": "Actual token count of assembled context"
    },
    "artifacts_included": {
      "type": "array",
      "items": { "$ref": "#/definitions/IncludedArtifact" }
    },
    "overflow": {
      "$ref": "#/definitions/OverflowManifest"
    },
    "audit": {
      "$ref": "#/definitions/AuditTrail"
    }
  },
  "definitions": {
    "IncludedArtifact": {
      "type": "object",
      "required": ["id", "source", "domain", "category", "title", "tokens"],
      "properties": {
        "id": { "type": "string" },
        "source": { "type": "string" },
        "domain": { "type": "string" },
        "category": { "type": "string" },
        "title": { "type": "string" },
        "tokens": { "type": "integer" }
      }
    },
    "OverflowManifest": {
      "type": "object",
      "required": ["count", "total_tokens", "artifacts"],
      "properties": {
        "count": {
          "type": "integer",
          "description": "Number of overflow artifacts"
        },
        "total_tokens": {
          "type": "integer",
          "description": "Total tokens in overflow"
        },
        "artifacts": {
          "type": "array",
          "items": { "$ref": "#/definitions/OverflowArtifact" }
        }
      }
    },
    "OverflowArtifact": {
      "type": "object",
      "required": ["id", "source", "domain", "title", "tokens"],
      "properties": {
        "id": { "type": "string" },
        "source": { "type": "string" },
        "domain": { "type": "string" },
        "title": { "type": "string" },
        "tokens": { "type": "integer" }
      }
    },
    "AuditTrail": {
      "type": "object",
      "properties": {
        "candidates_evaluated": { "type": "integer" },
        "discarded": {
          "type": "array",
          "items": { "$ref": "#/definitions/DiscardRecord" }
        },
        "stages": { "$ref": "#/definitions/StageStats" },
        "timing_ms": { "$ref": "#/definitions/StageTiming" }
      }
    },
    "DiscardRecord": {
      "type": "object",
      "required": ["id", "stage", "reason", "detail"],
      "properties": {
        "id": { "type": "string" },
        "stage": {
          "type": "string",
          "enum": ["hierarchical_filter", "metadata_filter", "token_budget"]
        },
        "reason": { "type": "string" },
        "detail": { "type": "string" }
      }
    },
    "StageStats": {
      "type": "object",
      "properties": {
        "hierarchical_filter": { "$ref": "#/definitions/InOut" },
        "metadata_filter": { "$ref": "#/definitions/InOut" },
        "priority_ordering": { "$ref": "#/definitions/InOut" },
        "token_budget": { "$ref": "#/definitions/InOut" }
      }
    },
    "InOut": {
      "type": "object",
      "properties": {
        "in": { "type": "integer" },
        "out": { "type": "integer" }
      }
    },
    "StageTiming": {
      "type": "object",
      "properties": {
        "total": { "type": "integer" },
        "hierarchical_filter": { "type": "integer" },
        "metadata_filter": { "type": "integer" },
        "late_materialization": { "type": "integer" },
        "priority_ordering": { "type": "integer" },
        "token_budget": { "type": "integer" }
      }
    }
  }
}
```

### 2.3 Error Response

```json
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "ErrorResponse",
  "type": "object",
  "required": ["error", "detail"],
  "properties": {
    "error": {
      "type": "string",
      "enum": [
        "validation_error",
        "rules_not_found",
        "provider_unavailable",
        "internal_error"
      ]
    },
    "detail": {
      "type": "string",
      "description": "Human-readable error message"
    },
    "field": {
      "type": "string",
      "description": "Field name for validation errors"
    },
    "available": {
      "type": "array",
      "items": { "type": "string" },
      "description": "Available options for not_found errors"
    },
    "provider": {
      "type": "string",
      "description": "Provider name for provider errors"
    }
  }
}
```

