## 3. Configuration Schemas (YAML)

### 3.1 Provider Configuration

```yaml
# config/providers.yaml
# Schema definition (for documentation)

# providers:
#   <provider-name>:
#     type: string (required) - Provider implementation type
#     base_url: string - HTTP endpoint for remote providers
#     timeout_ms: integer - Request timeout in milliseconds (default: 5000)
#     enabled: boolean - Whether provider is active (default: true)
#     api_token: string - Auth token (supports ${ENV_VAR} syntax)

# Example:
providers:
  artifact-engine:
    type: artifact_engine
    base_url: http://localhost:3002
    timeout_ms: 5000
    enabled: true

  paperless:
    type: paperless_ngx
    base_url: http://localhost:8000
    api_token: "${PAPERLESS_API_TOKEN}"
    timeout_ms: 10000
    enabled: false
```

**JSON Schema for Provider Configuration:**

```json
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "ProvidersConfig",
  "type": "object",
  "required": ["providers"],
  "properties": {
    "providers": {
      "type": "object",
      "additionalProperties": {
        "$ref": "#/definitions/ProviderConfig"
      }
    }
  },
  "definitions": {
    "ProviderConfig": {
      "type": "object",
      "required": ["type"],
      "properties": {
        "type": {
          "type": "string",
          "description": "Provider implementation type"
        },
        "base_url": {
          "type": "string",
          "format": "uri"
        },
        "timeout_ms": {
          "type": "integer",
          "minimum": 100,
          "default": 5000
        },
        "enabled": {
          "type": "boolean",
          "default": true
        },
        "api_token": {
          "type": "string"
        }
      }
    }
  }
}
```

### 3.2 Priority Rules Configuration

```yaml
# config/priority_rules/default.yaml

name: default
description: Standard priority ordering

ordering:
  - field: priority
    direction: desc
  - field: domain
    values: [cnc, business, research]
  - field: updated_at
    direction: desc

filters:
  max_age_days: 365
  exclude_tags:
    - deprecated
    - draft
  min_priority: 0
```

**JSON Schema for Priority Rules:**

```json
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "PriorityRules",
  "type": "object",
  "required": ["name", "ordering"],
  "properties": {
    "name": {
      "type": "string",
      "description": "Rule set identifier"
    },
    "description": {
      "type": "string"
    },
    "ordering": {
      "type": "array",
      "items": { "$ref": "#/definitions/OrderingRule" },
      "minItems": 1
    },
    "filters": {
      "$ref": "#/definitions/FilterRules"
    }
  },
  "definitions": {
    "OrderingRule": {
      "type": "object",
      "required": ["field"],
      "properties": {
        "field": {
          "type": "string",
          "enum": ["priority", "domain", "category", "updated_at", "token_count"]
        },
        "direction": {
          "type": "string",
          "enum": ["asc", "desc"],
          "default": "asc"
        },
        "values": {
          "type": "array",
          "items": { "type": "string" },
          "description": "Explicit ordering for categorical fields"
        }
      }
    },
    "FilterRules": {
      "type": "object",
      "properties": {
        "max_age_days": {
          "type": "integer",
          "minimum": 1
        },
        "exclude_tags": {
          "type": "array",
          "items": { "type": "string" }
        },
        "min_priority": {
          "type": "integer"
        }
      }
    }
  }
}
```

### 3.3 Application Configuration

```yaml
# config/app.yaml

server:
  host: 0.0.0.0
  port: 3003
  workers: 4

logging:
  level: INFO
  format: json  # or "text" for development

defaults:
  token_budget: 8000
  priority_rules: default
  encoding: cl100k_base
  include_audit: false

paths:
  providers_config: /etc/cull/providers.yaml
  priority_rules_dir: /etc/cull/priority_rules/
```

**JSON Schema for Application Configuration:**

```json
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "AppConfig",
  "type": "object",
  "properties": {
    "server": {
      "type": "object",
      "properties": {
        "host": { "type": "string", "default": "0.0.0.0" },
        "port": { "type": "integer", "default": 3003 },
        "workers": { "type": "integer", "default": 4 }
      }
    },
    "logging": {
      "type": "object",
      "properties": {
        "level": {
          "type": "string",
          "enum": ["DEBUG", "INFO", "WARNING", "ERROR"],
          "default": "INFO"
        },
        "format": {
          "type": "string",
          "enum": ["json", "text"],
          "default": "json"
        }
      }
    },
    "defaults": {
      "type": "object",
      "properties": {
        "token_budget": { "type": "integer", "default": 8000 },
        "priority_rules": { "type": "string", "default": "default" },
        "encoding": { "type": "string", "default": "cl100k_base" },
        "include_audit": { "type": "boolean", "default": false }
      }
    },
    "paths": {
      "type": "object",
      "properties": {
        "providers_config": { "type": "string" },
        "priority_rules_dir": { "type": "string" }
      }
    }
  }
}
```

